HITData.Materials = {}
HITData.ManualMaterials = {}

function HITData:IsHousingMaterial(itemID)
    itemID = tonumber(itemID)
    return itemID and (self.Materials[itemID] == true or self.ManualMaterials[itemID] == true) or false
end

function HITData:GetUsageNames(itemID, limit)
    itemID = tonumber(itemID)
    limit = limit or 8
    local out = {}
    if not itemID then return out end
    for decorID, info in pairs(self.DecorItems) do
        for _, mat in ipairs(info.materials or {}) do
            if tonumber(mat.id) == itemID then
                out[#out + 1] = info.name or ("Decor #" .. tostring(decorID))
                if #out >= limit then table.sort(out) return out end
            end
        end
    end
    table.sort(out)
    return out
end

function HITData:GetVendorList()
    local grouped, results = {}, {}
    local function append(vendor, item)
        local key = table.concat({ tostring(vendor.npcId or 0), tostring(vendor.location or "Unknown"), tostring(vendor.coordX or 0), tostring(vendor.coordY or 0) }, "|")
        local row = grouped[key]
        if not row then
            row = { npcID = vendor.npcId, name = vendor.name or "Unknown Vendor", zone = vendor.location or "Unknown", mapID = nil, x = vendor.coordX, y = vendor.coordY, currency = vendor.currency or (vendor.currencyId and ("Currency #" .. tostring(vendor.currencyId))) or "HousingItemTracker", requirementLabel = vendor.currency or nil, sourceTag = "hit", items = {}, mapTexture = vendor.mapTexture }
            grouped[key] = row
            results[#results + 1] = row
        end
        row.items[#row.items + 1] = item
    end
    for decorID, info in pairs(self.DecorItems) do
        for _, vendor in ipairs(info.vendors or {}) do
            append(vendor, { decorID = decorID, name = info.name, sourceType = "vendor", sourceLabel = "HousingItemTracker", requirementText = info.quest or info.achievement or info.profession or vendor.currency, isCollected = false })
        end
    end
    table.sort(results, function(a,b) if (a.zone or "") ~= (b.zone or "") then return (a.zone or "") < (b.zone or "") end return (a.name or "") < (b.name or "") end)
    return results
end

function HITData:GetVendorsForMap(mapID, includeParent)
    local out = {}
    for _, vendor in ipairs(self:GetVendorList()) do
        if vendor.mapID and vendor.x and vendor.y and (not mapID or vendor.mapID == mapID) then
            out[#out + 1] = vendor
        end
    end
    return out
end

function HITData:GetAchievementEntries()
    local results = {}
    for decorID, info in pairs(self.DecorItems) do
        if info.achievementId or info.achievement then
            results[#results + 1] = { entryType = "achievement", key = tostring(info.achievementId or info.achievement or decorID), title = info.name or ("Decor #" .. tostring(decorID)), subtitle = info.achievement or (info.achievementId and ("Achievement #" .. tostring(info.achievementId))) or "HousingItemTracker", detail = table.concat({info.category or "Unknown category", info.subcategory or "Unknown subcategory", info.quest and ("Quest: " .. info.quest) or nil}, " • "), decorIds = { decorID }, owned = 0, total = 1 }
        end
    end
    table.sort(results, function(a,b) return (a.title or "") < (b.title or "") end)
    return results
end

function HITData:GetQuestEntries()
    local results = {}
    for decorID, info in pairs(self.DecorItems) do
        if info.questId or info.quest then
            results[#results + 1] = { entryType = "quest", key = tostring(info.questId or info.quest or decorID), title = info.name or ("Decor #" .. tostring(decorID)), subtitle = info.quest or (info.questId and ("Quest #" .. tostring(info.questId))) or "HousingItemTracker", detail = table.concat({info.category or "Unknown category", info.subcategory or "Unknown subcategory", info.achievement and ("Achievement: " .. info.achievement) or nil}, " • "), decorIds = { decorID }, owned = 0, total = 1 }
        end
    end
    table.sort(results, function(a,b) return (a.title or "") < (b.title or "") end)
    return results
end

function HITData:GetProfessionEntries()
    local results = {}
    for decorID, info in pairs(self.DecorItems) do
        if info.profession then
            results[#results + 1] = { entryType = "profession", key = tostring(decorID), title = info.name or ("Decor #" .. tostring(decorID)), subtitle = info.profession, detail = table.concat({info.category or "Unknown category", info.subcategory or "Unknown subcategory", (#(info.materials or {}) > 0) and ("Materials: " .. tostring(#(info.materials or {}))) or nil}, " • "), decorIds = { decorID }, owned = 0, total = 1 }
        end
    end
    table.sort(results, function(a,b) return (a.subtitle or "") < (b.subtitle or "") end)
    return results
end

function HITData:GetTrackerEntries()
    local materialCount, manualCount, decorCount = 0, 0, 0
    for _ in pairs(self.Materials) do materialCount = materialCount + 1 end
    for _ in pairs(self.ManualMaterials) do manualCount = manualCount + 1 end
    for _ in pairs(self.DecorItems) do decorCount = decorCount + 1 end
    return {
        { title = "Decor Database", subtitle = tostring(decorCount) .. " donor decor records", detail = "HousingItemTracker donor decor database ingested into Villa for vendor maps, tooltip sourcing, and tracker workflows." },
        { title = "Crafting Materials", subtitle = tostring(materialCount) .. " tracked materials", detail = "Materials marked by HousingItemTracker as housing-relevant crafting inputs." },
        { title = "Manual Materials", subtitle = tostring(manualCount) .. " manual overrides", detail = "Extra donor material IDs manually maintained by HousingItemTracker." },
    }
end